#pragma once
#include "strata/kernels/original_mtp53_native_token_boundary.hpp"
#include "strata/kernels/original_mtp53_exact_vector_bytes.hpp"
// New explicit original native mode, no stock RT MTP ownership or target math.
#include "strata/kernels/original_mtp53_shifted_joint_checkpoint.hpp"
#include "strata/kernels/original_mtp53_serving_slots.hpp"
#include "strata/core/conversation_snapshot.hpp"
#include "strata/core/conversation_memory.hpp"
#include "strata/kernels/original_mtp53_shifted_joint_checkpoint_file.hpp"
namespace strata::kernels::original_mtp53 {
class OriginalServeContext53 final {
 std::shared_ptr<const OriginalDraftWeights53> weights_;std::unique_ptr<OriginalDraftSession53> admission_;OriginalDraftSlotOwner53 admission_owner_{0,0};
 std::unique_ptr<OriginalServingSlots53> slots_;OriginalShiftedJointCache53 cache_;std::string draft_contract_,target_contract_;bool failed_=false;size_t cache_budget_,min_free_;std::shared_ptr<const OriginalShiftedJointCheckpoint53> last_published_;
public:
 OriginalServeContext53(const char* path,const OriginalDraftIdentity53& identity,const sycl::queue& last,int slots,size_t cache_bytes,size_t min_free,const std::string& draft_contract,const std::string& target_contract)
 :weights_(std::make_shared<OriginalDraftWeights53>(path,identity,last,1)),admission_(std::make_unique<OriginalDraftSession53>(weights_,OriginalDraftSlotOwner53{0,0},last,1)),slots_(std::make_unique<OriginalServingSlots53>(weights_,last,slots)),cache_(cache_bytes),draft_contract_(draft_contract),target_contract_(target_contract),cache_budget_(cache_bytes),min_free_(min_free){if(!checkpoint_sha53(draft_contract_) || !checkpoint_sha53(target_contract_))throw std::runtime_error("original serving actual draft/target contract digests required");}
 void bind_target(strata::core::Verifier& first,strata::core::Verifier& last){slots_->bind_target(first,last);}
 OriginalServingSlots53& slots(){if(failed_)throw std::runtime_error("original serving context failure latched");return *slots_;}
 const std::string& draft_contract()const{return draft_contract_;}const std::string& target_contract()const{return target_contract_;}
 void begin_admission(OriginalDraftSlotOwner53 who){if(failed_)throw std::runtime_error("original admission failed");try{if(admission_owner_.rid)admission_->release_owner(admission_owner_);admission_->reset_fresh({0,0},who);admission_owner_=who;}catch(...){failed_=true;std::fprintf(stderr,"MTP53_SERVING_FATAL owned_draft_operation=1\n");std::fflush(stderr);std::_Exit(86);}}
 void teacher(const float* rows,int T,int64_t p0,const std::vector<int32_t>& actual_prompt){if(failed_)throw std::runtime_error("original teacher failed");try{if(!rows || p0<0 || T<1 || p0+T>=int64_t(actual_prompt.size()) || admission_->cells(admission_owner_)!=p0)throw std::runtime_error("original LAST teacher prefix differs");for(int t=0;t<T;++t)admission_->advance_actual(admission_owner_,actual_prompt[size_t(p0+t+1)],rows+size_t(t)*10240);}catch(...){failed_=true;std::fprintf(stderr,"MTP53_SERVING_FATAL owned_draft_operation=1\n");std::fflush(stderr);std::_Exit(86);}}
 void teacher(const float* rows,int T,int64_t p0,const std::vector<int64_t>& actual_prompt){teacher(rows,T,p0,original_tokens32_53(actual_prompt));}
 void admission_committed(int64_t base,int64_t actual_next,const float* actual_hidden){if(failed_)throw std::runtime_error("original admission commit failed");try{if(admission_->cells(admission_owner_)!=base)throw std::runtime_error("original admission target count differs");admission_->advance_actual(admission_owner_,original_token32_53(actual_next),actual_hidden);}catch(...){failed_=true;std::fprintf(stderr,"MTP53_SERVING_FATAL owned_draft_operation=1\n");std::fflush(stderr);std::_Exit(86);}}
 ShiftedOriginalCheckpoint53 admission_checkpoint(const std::vector<int32_t>& target_prefix){return admission_->export_shifted(admission_owner_,target_prefix,draft_contract_,target_contract_);}
 void move_admission_to_slot(int slot,OriginalDraftSlotOwner53 who,const std::vector<int32_t>& target_prefix,int64_t actual_lookahead){try{auto c=admission_checkpoint(target_prefix);slots().restore_checkpoint(slot,who,c,c.envelope_sha,target_prefix,original_token32_53(actual_lookahead),draft_contract_,target_contract_);admission_->release_owner(admission_owner_);admission_owner_={0,0};}catch(...){std::fprintf(stderr,"MTP53_SERVING_FATAL partial_slot_admission=1\n");std::fflush(stderr);std::_Exit(86);}}
 std::shared_ptr<const OriginalShiftedJointCheckpoint53> capture(strata::core::SessionState& first,strata::core::SessionState& last,const strata::core::ModelGeometry& geometry,const std::vector<int32_t>& prefix,const ShiftedOriginalCheckpoint53& original){
  if(prefix!=original.target_inputs || first.layer_lo!=0 || first.layer_hi!=24 || last.layer_lo!=24 || last.layer_hi!=48)throw std::runtime_error("original capture actual paired prefix/carve differs");
  std::array<strata::core::SavedConversation,2> images;std::array<std::array<int32_t,2>,2> previous;const std::vector<strata::core::ConversationImageKey> no_images;const std::vector<strata::core::ConversationCheckpoint> no_checks;strata::core::ConversationView view{prefix,no_images,no_checks,true};std::string error;
  for(int i=0;i<2;++i){const strata::core::OnDevice on(i);dpct::get_current_device().queues_wait_and_throw();auto& state=i==0?first:last;previous[i]={state.ple_prev[0],state.ple_prev[1]};size_t need=0;if(!strata::core::conversation_snapshot_bytes(view,state,geometry,(const strata::core::QsaState*)nullptr,need,error) || !strata::core::conversation_memory_admit(strata::core::conversation_available_memory(),need+(41u<<20),min_free_))throw std::runtime_error("original paired capture RAM admission failed");if(!strata::core::conversation_snapshot_save(images[i],view,state,geometry,(const strata::core::QsaState*)nullptr,error))throw std::runtime_error(error);}
  return std::make_shared<OriginalShiftedJointCheckpoint53>(std::move(images),ShiftedOriginalCheckpoint53(original),previous);
 }
 bool publish_admission(strata::core::SessionState& first,strata::core::SessionState& last,const strata::core::ModelGeometry& geometry,const std::vector<int32_t>& prefix){if(!cache_budget_ || prefix.empty() || !admission_owner_.rid)return false;return publish(capture(first,last,geometry,prefix,admission_checkpoint(prefix)));}
 bool publish_slot(int slot,OriginalDraftSlotOwner53 who,strata::core::SessionState& first,strata::core::SessionState& last,const strata::core::ModelGeometry& geometry,const std::vector<int32_t>& prefix){if(!cache_budget_)return false;return publish(capture(first,last,geometry,prefix,slots().checkpoint(slot,who,prefix,draft_contract_,target_contract_)));}
 void restore_targets(const std::shared_ptr<const OriginalShiftedJointCheckpoint53>& image,strata::core::SessionState& first,strata::core::SessionState& last,const strata::core::ModelGeometry& geometry){
  if(!image || image->original().current.draft_contract_sha!=draft_contract_ || image->original().current.target_contract_sha!=target_contract_)throw std::runtime_error("original current joint source differs");std::string error;
  for(int i=0;i<2;++i){const strata::core::OnDevice on(i);if(!strata::core::conversation_snapshot_validate(image->targets()[i],i==0?first:last,geometry,(const strata::core::QsaState*)nullptr,error))throw std::runtime_error(error);}
  try{for(int i=0;i<2;++i){const strata::core::OnDevice on(i);auto& state=i==0?first:last;dpct::get_current_device().queues_wait_and_throw();if(strata::core::conversation_snapshot_restore(image->targets()[i],state,geometry,(const strata::core::QsaState*)nullptr,error)!=strata::core::ConversationRestore::restored)throw std::runtime_error(error);dpct::get_current_device().queues_wait_and_throw();state.ple_prev[0]=image->ple_previous()[i][0];state.ple_prev[1]=image->ple_previous()[i][1];strata::core::ConversationCheckpoint got;got.ids=image->original().target_inputs;if(!strata::core::conversation_checkpoint_save(got,state,geometry,error))throw std::runtime_error(error);const auto& expected=image->targets()[i].live;if(!exact_vector_bytes53(got.gdn,expected.gdn) || !exact_vector_bytes53(got.ple,expected.ple) || !exact_vector_bytes53(got.tails,expected.tails) || !exact_vector_bytes53(got.dead,expected.dead) || !exact_vector_bytes53(got.block_pos,expected.block_pos) || image->targets()[i].kv.size()!=size_t(state.qsa_alloc))throw std::runtime_error("original target restore complete bytes differ");for(size_t j=0;j<image->targets()[i].kv.size();++j){uint64_t digest;if(!strata::core::conversation_kv_verify(image->targets()[i].kv[j],state.qsa_states[size_t(state.qsa_ord0)+j],geometry,image->original().target_inputs.size(),true,digest,error))throw std::runtime_error(error);}}}catch(...){std::fprintf(stderr,"MTP53_SERVING_FATAL partial_target_restore=1\n");std::fflush(stderr);std::_Exit(86);}
 }
 std::shared_ptr<const OriginalShiftedJointCheckpoint53> best(const std::vector<int32_t>& request,int64_t ceiling){auto found=cache_.best(request,draft_contract_,target_contract_);if(found && int64_t(found->original().target_inputs.size())>ceiling){std::vector<int32_t> bounded(request.begin(),request.begin()+std::min<size_t>(request.size(),size_t(std::max<int64_t>(ceiling,0))));return cache_.best(bounded,draft_contract_,target_contract_);}return found;}
 bool publish(std::shared_ptr<const OriginalShiftedJointCheckpoint53> image){if(failed_)throw std::runtime_error("original publication failed");if(!cache_budget_)return false;bool stored=cache_.put(image);if(stored)last_published_=std::move(image);return stored;}size_t bytes(){return cache_.charged_bytes();}
 void save_file(const std::filesystem::path& path,const std::array<strata::core::SessionFileIdentity,2>& ids){if(!last_published_)throw std::runtime_error("original complete published checkpoint absent");shifted_joint_file53::Publish status;shifted_joint_file53::save(path,*last_published_,ids,status);if(!status.published || !status.durable)throw std::runtime_error("original joint publication not durable");}
 void load_file(const std::filesystem::path& path,const std::string& pinned,const std::array<strata::core::SessionFileIdentity,2>& ids,const std::array<strata::core::SessionReadLimits,2>& limits){auto image=shifted_joint_file53::read_tree(path,pinned,ids,limits);if(image->original().current.draft_contract_sha!=draft_contract_ || image->original().current.target_contract_sha!=target_contract_ || !publish(image))throw std::runtime_error("original loaded complete cache identity/budget differs");}
 std::shared_ptr<const OriginalShiftedJointCheckpoint53> best(const std::vector<int64_t>& request,int64_t ceiling){return best(original_tokens32_53(request),ceiling);}
 void restore_admission(const std::shared_ptr<const OriginalShiftedJointCheckpoint53>& image,const std::vector<int32_t>& prefix,int64_t next){try{admission_->import_shifted(admission_owner_,image->original(),image->original().envelope_sha,prefix,original_token32_53(next),draft_contract_,target_contract_);}catch(...){std::fprintf(stderr,"MTP53_SERVING_FATAL partial_draft_restore=1\n");std::fflush(stderr);std::_Exit(86);}}
};
}
